from pathlib import Path
import base64, gzip, subprocess, tempfile, os

DATA = """"""
patch_bytes = gzip.decompress(base64.b64decode(DATA))
fd, patch_path = tempfile.mkstemp(prefix="wakeguard-v164-", suffix=".patch")
try:
    with os.fdopen(fd, "wb") as f:
        f.write(patch_bytes)
    subprocess.run(["patch", "-p1", "--forward", "-i", patch_path], cwd="WakeGuard/app", check=True)
finally:
    try:
        os.unlink(patch_path)
    except OSError:
        pass
print("WakeGuard v1.6.4 stopwatch + pre-alarm notification patch applied")
